CREATE OR REPLACE FUNCTION public.check_delivery(_pincode text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.shipping_rules; BEGIN IF _pincode !~ '^[1-9][0-9]{5}$' THEN RAISE EXCEPTION 'Invalid PIN'; END IF; SELECT * INTO s FROM public.shipping_rules WHERE pincode=_pincode AND active; IF NOT FOUND THEN RETURN jsonb_build_object('serviceable',false,'cod_enabled',false); END IF; RETURN jsonb_build_object('serviceable',true,'fee_paise',s.fee_paise,'min_days',s.min_days,'max_days',s.max_days,'cod_enabled',true); END $$;
CREATE OR REPLACE FUNCTION public.scrub_retained_requests() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND display_name='' AND phone IS NULL AND preferences='{}') THEN UPDATE public.order_requests SET reason='Account deleted',staff_note=NULL WHERE user_id=auth.uid(); ELSE RAISE EXCEPTION 'Deletion preparation required'; END IF; END $$;
REVOKE ALL ON FUNCTION public.scrub_retained_requests() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.scrub_retained_requests() TO authenticated;